\section{Introduction}

\subsection{Gilbert's disc model and its conditioning}

In Gilbert's disc model, introduced in 1961 as a model for radio communication networks,
points of a homogeneous Poisson process of intensity $\lambda$ in $\mathbb{R}^2$ are joined
whenever their distance is below a fixed threshold. The model exhibits a sharp phase
transition: there is a critical intensity $\lambda_c$ below which all clusters are almost
surely finite and above which an infinite cluster exists almost surely. The precise value of
$\lambda_c$ is unknown; simulations give $\lambda_c R^2\approx 0.3591$, and no closed form
is expected.

The model considered here replaces the Poisson process by a strongly conditioned one: the
process is conditioned to have exactly one point in each unit cell of the square lattice
$\mathbb{Z}^2$, with the point uniform in its cell and the cells independent. Equivalently,
the point of cell $(i,j)$ is $(i+U_{i,j},\,j+V_{i,j})$ with $(U_{i,j},V_{i,j})$ independent
and uniform on $[0,1]^2$.

This conditioning eliminates both of the mechanisms that dominate Poisson percolation:
clumping (which creates dense local clusters at low intensity) and vacancy (which creates
arbitrarily large empty regions at any intensity). What remains is a maximally rigid point
process: the number of points in any large region equals the number of cells the region
meets, up to a boundary error, so the model is hyperuniform in the strongest sense.

\subsection{Three geometric thresholds}

Because the point locations range over a compact parameter space $[0,1]^{\mathbb{Z}^2}$, the
conditioned model supports questions that are meaningless for the Poisson model: questions
about \emph{all} placements simultaneously, or about the \emph{existence} of a placement
with a given property. This is what produces the three critical radii studied here. The
almost-sure percolation threshold of the random model, which we denote $R_c$, satisfies
$R_{\min}\le R_c$ trivially and is not the subject of this paper; our results are
placement-uniform and therefore hold for every realisation.

\subsection{Results}

The main results are the two-sided bounds
\[
\tfrac13\le R_{\min}\le\tfrac12,\qquad
\tfrac13\le R_{\mathrm{conn}}\le 1,\qquad
\tfrac{\sqrt{17}}{2}\le R_{\mathrm{full}}\le\sqrt5,
\]
the ordering $R_{\min}\le R_{\mathrm{conn}}\le R_{\mathrm{full}}$, and the confinement
theorem: for $R<\tfrac13$, every component of every placement is contained in a $3\times3$
block of cells.

\section{The model}

\begin{definition}[Placement]
A \emph{placement} (or \emph{configuration}) is a family
$\off:\mathbb{Z}^2\to[0,1]^2$, $c\mapsto(\off_1(c),\off_2(c))$, of offsets, one for each
cell of the grid. The \emph{point of the cell} $c=(c_1,c_2)$ is
\[
p(c)=\big(x(c),y(c)\big):=\big(c_1+\off_1(c),\;c_2+\off_2(c)\big)
\in[c_1,c_1+1]\times[c_2,c_2+1].
\]
\end{definition}

We work with the closed cell $[0,1]^2$ of admissible offsets. This is a compactification of
the open cell used by the random model; it is harmless there (the boundary has measure zero)
and it makes the extremal placements below legitimate objects rather than limits of
legitimate objects.

\begin{definition}[Gilbert graph]
For $R\in\mathbb{R}$ and a placement $C$, the \emph{Gilbert graph} $G_R(C)$ is the simple
graph on the vertex set $\mathbb{Z}^2$ (the cells) with
\[
c\sim c'\iff c\ne c'\ \text{ and }\ \|p(c)-p(c')\|<R .
\]
We write $d(c,c')=\|p(c)-p(c')\|$ and
$d^2(c,c')=(x(c)-x(c'))^2+(y(c)-y(c'))^2$.
\end{definition}

The graph is symmetric and loopless by construction, and monotone in $R$: if $R\le R'$ then
$G_R(C)\subseteq G_{R'}(C)$, hence reachability in $G_R(C)$ implies reachability in
$G_{R'}(C)$. An edge can exist only if $R>0$.

\begin{definition}\label{def:radii}
Define
\begin{align*}
\mathcal{P}&=\{R:\ \exists\text{ a placement }C\text{ and a cell }c\text{ with the component
of }c\text{ in }G_R(C)\text{ infinite}\},\\
\mathcal{C}&=\{R:\ \exists\text{ a placement }C\text{ with }G_R(C)\text{ connected}\},\\
\mathcal{F}&=\{R:\ \forall\text{ placements }C,\ G_R(C)\text{ is connected}\},
\end{align*}
and set $R_{\min}=\inf\mathcal{P}$, $R_{\mathrm{conn}}=\inf\mathcal{C}$,
$R_{\mathrm{full}}=\inf\mathcal{F}$.
\end{definition}

By monotonicity each set is upward closed, so each infimum is a genuine threshold. Moreover
$\mathcal{F}\subseteq\mathcal{C}\subseteq\mathcal{P}$, whence
\begin{equation}\label{eq:ordering}
R_{\min}\le R_{\mathrm{conn}}\le R_{\mathrm{full}} .
\end{equation}

\section{Elementary geometry of edges}

Throughout, $C$ is a placement and $R$ a radius.

\begin{lemma}[Coordinate bounds along an edge]\label{lem:coord}
If $c\sim c'$ in $G_R(C)$ then $|x(c)-x(c')|<R$ and $|y(c)-y(c')|<R$.
\end{lemma}

\begin{proof}
Each coordinate difference is at most the Euclidean distance in absolute value.
\end{proof}

\begin{lemma}[Neighbours are grid-adjacent for $R\le1$]\label{lem:gridadj}
If $R\le1$ and $c\sim c'$ then $|c'_1-c_1|\le1$ and $|c'_2-c_2|\le1$.
\end{lemma}

\begin{proof}
Write $c'_1-c_1=(x(c')-x(c))+(\off_1(c)-\off_1(c'))$. The first bracket has absolute value
$<R\le1$ by Lemma~\ref{lem:coord}, the second at most $1$ since both offsets lie in $[0,1]$.
Hence $|c'_1-c_1|<2$, and being an integer it is at most $1$. The vertical case is
identical.
\end{proof}

\begin{lemma}[Diameter of a grid-adjacent pair]\label{lem:sqrt5}
If $c,c'$ are cells sharing an edge, $|c_1-c'_1|+|c_2-c'_2|=1$, then $d(c,c')\le\sqrt5$ for
every placement.
\end{lemma}

\begin{proof}
Say $c'=(c_1+1,c_2)$. Then $x(c')-x(c)=1+\off_1(c')-\off_1(c)\in[0,2]$ and
$|y(c')-y(c)|=|\off_2(c')-\off_2(c)|\le1$, so $d^2\le4+1=5$.
\end{proof}

\begin{lemma}[Line-crossing lemma]\label{lem:cross}
Let $R<1$ and $c\sim c'$ with $c_1\ne c'_1$. Then there is $K\in\mathbb{Z}$ with
$\{c_1,c'_1\}\subseteq\{K-1,K\}$ and $|x(c)-K|<R$, $|x(c')-K|<R$. The analogous statement
holds for rows, producing $J\in\mathbb{Z}$ with $\{c_2,c'_2\}\subseteq\{J-1,J\}$ and
$|y(c)-J|<R$, $|y(c')-J|<R$.
\end{lemma}

\begin{proof}
By Lemma~\ref{lem:gridadj}, $c'_1=c_1\pm1$; suppose $c'_1=c_1+1$ and take $K=c_1+1$. Then
$x(c)\le c_1+1=K\le c'_1\le x(c')$, so the points straddle the line $x=K$; since
$|x(c)-x(c')|<R$, we get $K-x(c)\le x(c')-x(c)<R$ and $x(c')-K\le x(c')-x(c)<R$. The case
$c'_1=c_1-1$ is symmetric with $K=c_1$.
\end{proof}

Lemma~\ref{lem:cross} is the structural fact driving the subcritical analysis: an edge that
advances a column certifies that \emph{both} of its endpoints hug the same vertical grid
line.

\begin{lemma}[Integer separation]\label{lem:intsep}
If $K,K'\in\mathbb{Z}$ and $|K-K'|<1$ then $K=K'$.
\end{lemma}

\begin{lemma}[Grid connectivity criterion]\label{lem:gridconn}
If every pair of horizontally adjacent cells $(i,j),(i+1,j)$ and every pair of vertically
adjacent cells $(i,j),(i,j+1)$ is an edge of $G_R(C)$, then $G_R(C)$ is connected.
\end{lemma}

\begin{proof}
Induction along $\mathbb{Z}$ in each direction shows that $(i,j)$ and $(i',j)$ are
reachable from one another for all $i,i'$, and likewise $(i,j)$ and $(i,j')$. Concatenating
a horizontal and a vertical path connects any two cells.
\end{proof}

\section{Deterministic non-percolation below $1/3$}

\begin{theorem}[Confinement]\label{thm:confine}
Let $R<\tfrac13$. Then for \emph{every} placement $C$ and all cells $c,d$, if $d$ is
reachable from $c$ in $G_R(C)$ then $|d_1-c_1|\le1$ and $|d_2-c_2|\le1$.
\end{theorem}

\begin{corollary}\label{cor:noperc}
For $R<\tfrac13$ and every placement, every connected component of $G_R(C)$ lies in a
$3\times3$ block of cells; in particular every component is finite and no placement
percolates. Hence $R_{\min}\ge\tfrac13$.
\end{corollary}

\subsection{The invariant}

Fix $R$ with $0<R<\tfrac13$ (for $R\le0$ there are no edges) and integers $K,J$. For an
ordered pair of cells $(p,c)$ --- ``previous'' and ``current'' --- say that the
\emph{invariant} $\mathrm{Inv}(K,J;p,c)$ holds when
\begin{enumerate}
\item $p\ne c$;
\item $p_1,c_1\in\{K-1,K\}$ and $p_2,c_2\in\{J-1,J\}$;
\item \emph{(loose slack)} $|x(c)-K|<2R$ and $|y(c)-J|<2R$;
\item \emph{(tight slack)} if $p_1\ne c_1$ then $|x(c)-K|<R$; if $p_2\ne c_2$ then
$|y(c)-J|<R$.
\end{enumerate}
Informally: $K$ and $J$ are the only grid lines the path will ever cross; the current point
is always within $2R$ of both, and within $R$ of whichever it just crossed.

\begin{lemma}[Uniqueness of the crossed line]\label{lem:unique}
Assume $\mathrm{Inv}(K,J;p,c)$ and $R<\tfrac13$. If $K'\in\mathbb{Z}$ satisfies
$|x(c)-K'|<R$ then $K'=K$; likewise for rows.
\end{lemma}

\begin{proof}
$|K'-K|\le|K'-x(c)|+|x(c)-K|<R+2R=3R<1$; apply Lemma~\ref{lem:intsep}.
\end{proof}

\begin{lemma}[No two consecutive trivial steps]\label{lem:nodouble}
Let $R<\tfrac13$ and $c_0\sim c_1\sim c_2$ with $c_2\ne c_0$. Then $c_0,c_1,c_2$ cannot all
share the same column, nor can they all share the same row.
\end{lemma}

\begin{proof}
Suppose $(c_1)_1=(c_0)_1=(c_2)_1$. Since $c_0\ne c_1$ and $c_1\ne c_2$, both steps change
the row, so Lemma~\ref{lem:cross} produces $J_1,J_2$ with $|y(c_1)-J_1|<R$ and
$|y(c_1)-J_2|<R$; then $|J_1-J_2|<2R<1$ forces $J_1=J_2=:J$ by Lemma~\ref{lem:intsep}. Now
$(c_0)_2,(c_1)_2\in\{J-1,J\}$ with $(c_0)_2\ne(c_1)_2$, and $(c_1)_2,(c_2)_2\in\{J-1,J\}$
with $(c_1)_2\ne(c_2)_2$; hence $(c_2)_2=(c_0)_2$ and $c_2=c_0$, a contradiction.
\end{proof}

\begin{lemma}[Propagation]\label{lem:prop}
Assume $\mathrm{Inv}(K,J;p,c)$, $R<\tfrac13$, and let $c\sim c'$ with $c'\ne p$. Then
$\mathrm{Inv}(K,J;c,c')$.
\end{lemma}

\begin{proof}
Note $c\ne c'$. Three cases.

\emph{(a) The step changes the row only} ($c'_1=c_1$, $c'_2\ne c_2$).
Lemma~\ref{lem:cross} produces $J'$ with $c_2,c'_2\in\{J'-1,J'\}$, $|y(c)-J'|<R$ and
$|y(c')-J'|<R$; Lemma~\ref{lem:unique} gives $J'=J$. This yields the row part of (2) and
both slack conditions in $y$. For $x$ we must show $|x(c')-K|<2R$, which follows from
$|x(c')-K|\le|x(c')-x(c)|+|x(c)-K|<R+|x(c)-K|$ provided the tight slack $|x(c)-K|<R$ holds
at $c$. If $p_1\ne c_1$ this is hypothesis (4). If $p_1=c_1$, then $p_2\ne c_2$ (else
$p=c$), so the previous step also changed the row only, and by Lemmas~\ref{lem:cross} and
\ref{lem:unique} it crossed the same line $J$; the membership constraints then force
$p_2=c'_2$, hence $p=c'$, contradicting $c'\ne p$. The tight condition in $x$ at $c'$ is
vacuous since $c'_1=c_1$.

\emph{(b) The step changes the column only.} Symmetric to (a).

\emph{(c) The step changes both.} Lemma~\ref{lem:cross} applies in both coordinates and
Lemma~\ref{lem:unique} identifies the crossed lines as $K$ and $J$; both slacks are
refreshed to the tight value.
\end{proof}

\begin{lemma}[Initialisation]\label{lem:init}
Let $R<\tfrac13$ and $c_0\sim c_1\sim c_2$ with $c_2\ne c_0$. Then there are integers
$K\in\{(c_0)_1,(c_0)_1+1\}$ and $J\in\{(c_0)_2,(c_0)_2+1\}$ with
$\mathrm{Inv}(K,J;c_1,c_2)$.
\end{lemma}

\begin{proof}
We construct $K$; the construction of $J$ is symmetric and independent. If the second step
changes the column, take $K$ from Lemma~\ref{lem:cross} applied to $c_1\sim c_2$; both
slacks in $x$ at $c_2$ are then $<R$, and $K$ is adjacent to $(c_0)_1$ (if the first step
also changed the column, the line it crossed coincides with $K$ by
Lemma~\ref{lem:intsep}; otherwise $(c_1)_1=(c_0)_1$ and $K\in\{(c_1)_1,(c_1)_1+1\}$). If
the second step leaves the column unchanged, Lemma~\ref{lem:nodouble} forces the first step
to change it; take $K$ from Lemma~\ref{lem:cross} applied to $c_0\sim c_1$, so
$|x(c_1)-K|<R$ and $|x(c_2)-K|\le|x(c_2)-x(c_1)|+|x(c_1)-K|<2R$.
\end{proof}

\subsection{Proof of Theorem~\ref{thm:confine}}

\begin{proof}
Reachability is witnessed by a self-avoiding path $c=c_0,c_1,\dots,c_n=d$. If $n\le1$,
Lemma~\ref{lem:gridadj} gives the conclusion. If $n\ge2$, then $c_2\ne c_0$ by
self-avoidance, so Lemma~\ref{lem:init} supplies $K,J$ with $\mathrm{Inv}(K,J;c_1,c_2)$,
$K\in\{c_{0,1},c_{0,1}+1\}$ and $J\in\{c_{0,2},c_{0,2}+1\}$. Applying Lemma~\ref{lem:prop}
inductively (the hypothesis $c_{t+1}\ne c_{t-1}$ holds at each step by self-avoidance),
every $c_t$ with $t\ge2$ satisfies $c_{t,1}\in\{K-1,K\}$ and $c_{t,2}\in\{J-1,J\}$. Since
$K\in\{c_{0,1},c_{0,1}+1\}$ we get $|c_{t,1}-c_{0,1}|\le1$, and similarly for rows.
\end{proof}

\begin{remark}[Where $\tfrac13$ comes from]
The only quantitative input is Lemma~\ref{lem:unique}: tight slack $R$ plus loose slack $2R$
must be less than the integer gap $1$. If slack $R$ could be maintained throughout, the
argument would give $R_{\min}\ge\tfrac12$; the loss arises precisely from steps that fail to
refresh a coordinate.
\end{remark}

\section{Extremal placements}

\subsection{The line placement: percolation above $1/2$}

\begin{definition}\label{def:line}
The \emph{line placement} $L$ assigns $\off((i,0))=(\tfrac34,1)$ and
$\off((i,1))=(\tfrac14,0)$, with $\off(c)=(0,0)$ elsewhere. Thus
$p((i,0))=(i+\tfrac34,1)$ and $p((i,1))=(i+\tfrac14,1)$: every point of the two rows
$j\in\{0,1\}$ lies on the horizontal line $y=1$.
\end{definition}

\begin{lemma}\label{lem:linedist}
In the line placement, $d((i,1),(i,0))=\tfrac12$ and $d((i,0),(i+1,1))=\tfrac12$ for every
$i\in\mathbb{Z}$.
\end{lemma}

\begin{proof}
Both pairs lie on $y=1$, with $x$-coordinates $i+\tfrac14$ and $i+\tfrac34$ in the first
case, $i+\tfrac34$ and $i+\tfrac54$ in the second.
\end{proof}

\begin{theorem}[Percolating placement above $\tfrac12$]\label{thm:line}
For every $R>\tfrac12$ the Gilbert graph of the line placement has an infinite connected
component; explicitly, all cells $(n,0)$, $n\in\mathbb{Z}$, lie in the component of
$(0,0)$. Consequently $R_{\min}\le\tfrac12$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:linedist} the chain $(i,0)\sim(i+1,1)\sim(i+1,0)$ shows that $(i,0)$ and
$(i+1,0)$ lie in the same component for every $i$; induction gives an injection
$n\mapsto(n,0)$ of $\mathbb{N}$ into the component of $(0,0)$.
\end{proof}

\subsection{The centred placement: full connectivity above $1$}

\begin{definition}
The \emph{centred placement} $Z$ assigns $\off(c)=(\tfrac12,\tfrac12)$ for all $c$, so
$p((i,j))=(i+\tfrac12,j+\tfrac12)$.
\end{definition}

\begin{theorem}\label{thm:centre}
For every $R>1$ the Gilbert graph of the centred placement is connected. Consequently
$R_{\mathrm{conn}}\le1$.
\end{theorem}

\begin{proof}
Edge-adjacent cells have points at distance exactly $1<R$, so all grid edges are present;
apply Lemma~\ref{lem:gridconn}.
\end{proof}

\subsection{The cut placement: disconnection below $\sqrt{17}/2$}

\begin{definition}
The \emph{cut placement} $X$ assigns $\off(c)=(\tfrac12,1)$ if $c_2\ge1$ and
$\off(c)=(0,0)$ if $c_2\le0$; thus $p((i,j))=(i+\tfrac12,j+1)$ for $j\ge1$ and
$p((i,j))=(i,j)$ for $j\le0$.
\end{definition}

\begin{lemma}\label{lem:cutdist}
In the cut placement, if $c_2\ge1$ and $c'_2\le0$ then $d^2(c,c')\ge\tfrac{17}4$.
\end{lemma}

\begin{proof}
Vertically, $y(c)-y(c')=(c_2+1)-c'_2\ge2$ since $c_2\ge c'_2+1$. Horizontally,
$x(c)-x(c')=(c_1-c'_1)+\tfrac12$ is a half-integer, so $|x(c)-x(c')|\ge\tfrac12$. Hence
$d^2\ge4+\tfrac14=\tfrac{17}4$.
\end{proof}

\begin{theorem}[Persistent cut]\label{thm:cut}
For every $R\le\tfrac{\sqrt{17}}2$ the Gilbert graph of the cut placement is disconnected:
no cell with $c_2\ge1$ is reachable from any cell with $c'_2\le0$. Consequently
$R_{\mathrm{full}}\ge\tfrac{\sqrt{17}}2\approx2.0616$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:cutdist} no edge joins $\{c_2\ge1\}$ to $\{c_2\le0\}$, so the upper
half-plane of cells is closed under adjacency and hence, by induction along walks, under
reachability. Thus $(0,1)$ is not reachable from $(0,0)$.
\end{proof}

\subsection{Universal connectivity above $\sqrt5$}

\begin{theorem}\label{thm:full}
For every $R>\sqrt5$ and every placement $C$, the graph $G_R(C)$ is connected. Consequently
$R_{\mathrm{full}}\le\sqrt5\approx2.2360$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:sqrt5} all grid edges are present; apply Lemma~\ref{lem:gridconn}.
\end{proof}

\section{The critical radii}

\begin{theorem}[Geometric percolation threshold]
$\tfrac13\le R_{\min}\le\tfrac12$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:line} gives $(\tfrac12,\infty)\subseteq\mathcal{P}$, hence
$R_{\min}\le\tfrac12$; Corollary~\ref{cor:noperc} gives $R\ge\tfrac13$ for all
$R\in\mathcal{P}$.
\end{proof}

\begin{theorem}[Connecting threshold]
$\tfrac13\le R_{\mathrm{conn}}\le1$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:centre} gives $(1,\infty)\subseteq\mathcal{C}$. For the lower bound,
$\mathcal{C}\subseteq\mathcal{P}$ (in a connected graph on $\mathbb{Z}^2$ the component of
any cell is all of $\mathbb{Z}^2$), so Corollary~\ref{cor:noperc} applies.
\end{proof}

\begin{theorem}[Full-connectivity threshold]
$\tfrac{\sqrt{17}}2\le R_{\mathrm{full}}\le\sqrt5$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:full} gives the upper bound. For the lower bound let $R\in\mathcal{F}$;
then $R>0$ (a connected graph on $\mathbb{Z}^2$ has an edge, and edges require $R>0$), and
$R<\tfrac{\sqrt{17}}2$ would give $R^2<\tfrac{17}4$, contradicting
Theorem~\ref{thm:cut}.
\end{proof}

\begin{theorem}[Ordering]
$R_{\min}\le R_{\mathrm{conn}}\le R_{\mathrm{full}}$.
\end{theorem}

\begin{proof}
Immediate from $\mathcal{F}\subseteq\mathcal{C}\subseteq\mathcal{P}$, each infimum being
over a non-empty set bounded below.
\end{proof}

